#!/bin/sh
# The repo's deterministic checks. factory/bin/gate runs the main checkout's copy of
# this file inside a job's worktree; exit 0 means the gate passes.
# Generated by Eminzo from the files found in the repo: review it.
#
# Ruby: `bundle exec rspec` when the repo has a spec/ folder and `bundle exec rake test` (Minitest)
# when it has a test/ folder. No lint runs here: add `bundle exec rubocop` above the last lines.
# FACTORY_CHECK_MODE is "focused" while a builder iterates and "full" for the gate and the merge;
# in focused mode FACTORY_CHANGED_FILES names a file that lists the changed paths, one repo-relative
# path per line. Narrowing is a shortcut: an empty selection runs everything, and the full run
# below is the backstop.
set -e
MODE="${FACTORY_CHECK_MODE:-full}"
CHANGED="${FACTORY_CHANGED_FILES:-}"
# Read once, then unset, so a test that starts another factory process does not inherit them.
unset FACTORY_CHECK_MODE FACTORY_CHANGED_FILES

# The changed paths that still exist, one per line, prefixed with ./ so a name starting with - is never an option.
existing() { while IFS= read -r f; do [ -e "$f" ] && printf '%s\n' "./$f"; done < "$CHANGED"; return 0; }

if [ "$MODE" = focused ] && [ -n "$CHANGED" ] && [ -s "$CHANGED" ]; then
  # Narrow only when EVERY changed path is a spec or test file (a changed library file can break any test).
  rc=0
  grep -qvE '_spec\.rb$|_test\.rb$' "$CHANGED" || rc=$?
  if [ "$rc" -eq 1 ]; then
    specs=$(existing | grep '_spec\.rb$' || true)
    tests=$(existing | grep '_test\.rb$' || true)
    if [ -n "$specs" ] || [ -n "$tests" ]; then
      st=0
      if [ -n "$specs" ]; then printf '%s\n' "$specs" | tr '\n' '\0' | xargs -0 bundle exec rspec || st=$?; fi
      if [ -n "$tests" ]; then printf '%s\n' "$tests" | tr '\n' '\0' | xargs -0 bundle exec ruby -Itest -Ilib -e 'ARGV.each { |f| require File.expand_path(f) }' || st=$?; fi
      exit "$st"
    fi
  fi
fi

# Full mode: spec/ runs with rspec, test/ with Minitest through rake; a repo with both runs both.
if [ -d spec ]; then bundle exec rspec; fi
if [ -d test ] || [ ! -d spec ]; then bundle exec rake test; fi
